import{_ as s,C as n,c as a,o as i,a3 as e,G as r}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Operation types","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/warehouses/operation-types.md","filePath":"master/supply-chain/inventories/warehouses/operation-types.md","lastUpdated":1791902625000}'),d={name:"master/supply-chain/inventories/warehouses/operation-types.md"};function l(h,t,p,u,c,g){const o=n("ImagePopup");return i(),a("div",null,[t[0]||(t[0]=e('<h1 id="operation-types" tabindex="-1">Operation types <a class="header-anchor" href="#operation-types" aria-label="Permalink to &quot;Operation types&quot;">​</a></h1><p>An operation type is a template for a kind of stock job: receive, deliver, pick, pack and so on. It decides the document prefix, the default from and to locations and a few behaviours such as backorders. Each transfer you create belongs to one operation type.</p><blockquote><p><strong>In simple words:</strong> An operation type answers &quot;what kind of job is this?&quot; and fills in sensible defaults for it.</p></blockquote><p>Open <code>Inventory → Configurations → Warehouse Management → Operation Types</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Some fields show only when a setting is on:</p><ul><li><strong>Locations</strong> in <code>Inventory → Settings → Manage Warehouses</code> shows the <strong>Locations</strong> fieldset.</li><li><strong>Lots &amp; Serial Numbers</strong> in <code>Inventory → Settings → Manage Traceability</code> shows the <strong>Lots/Serial</strong> fieldset.</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows only <strong>Name</strong>, <strong>Company</strong> and <strong>Warehouse</strong>, 10 rows per page (14 in all). Tabs are <strong>All</strong> and <strong>Archived</strong>. You can group by type or warehouse and filter by <strong>Type</strong>, <strong>Warehouse</strong> or <strong>Company</strong>. Open a record to see the other fields.</p>',9)),r(o,{src:"/images1/inventory/optype_list.png",alt:"Operation Types list showing Receipts, Delivery Orders, Pick, Pack and the other types"}),t[1]||(t[1]=e('<h2 id="the-14-ready-made-types" tabindex="-1">The 14 ready-made types <a class="header-anchor" href="#the-14-ready-made-types" aria-label="Permalink to &quot;The 14 ready-made types&quot;">​</a></h2><p>Your dev warehouse has these types. For all of them the reservation method is <strong>At Confirm</strong> and the move type is <strong>As soon as possible</strong>.</p><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Prefix</th><th>Backorder</th><th>From to</th></tr></thead><tbody><tr><td>Receipts</td><td>Receipt</td><td>IN</td><td>Ask</td><td>Partners/Vendors to WH/Input</td></tr><tr><td>Delivery Orders</td><td>Delivery</td><td>OUT</td><td>Ask</td><td>WH/Output to Partners/Customers</td></tr><tr><td>Pick</td><td>Internal</td><td>PICK</td><td>Ask</td><td>WH/Stock to WH/Packing Zone</td></tr><tr><td>Pack</td><td>Internal</td><td>PACK</td><td>Ask</td><td>WH/Packing Zone to WH/Output</td></tr><tr><td>Quality Control</td><td>Internal</td><td>QC</td><td>Ask</td><td>WH/Input to WH/Quality Control</td></tr><tr><td>Storage</td><td>Internal</td><td>STOR</td><td>Ask</td><td>WH/Quality Control to WH/Stock</td></tr><tr><td>Internal Transfers</td><td>Internal</td><td>INT</td><td>Ask</td><td>WH/Stock to WH/Stock</td></tr><tr><td>Cross Dock</td><td>Internal</td><td>XD</td><td>Ask</td><td>WH/Input to WH/Output</td></tr><tr><td>Dropship</td><td>Dropship</td><td>DS</td><td>Ask</td><td>Partners/Vendors to Partners/Customers</td></tr><tr><td>Pick Components</td><td>Internal</td><td>PC</td><td>Ask</td><td>WH/Stock to WH/Pre-Production</td></tr><tr><td>Store Finished Product</td><td>Internal</td><td>SFP</td><td>Ask</td><td>WH/Post-Production to WH/Stock</td></tr><tr><td>Manufacturing</td><td>Manufacture</td><td>MO</td><td>Ask</td><td>WH/Pre-Production to WH/Post-Production</td></tr><tr><td>PoS Returns</td><td>Receipt</td><td>POSRET</td><td>Never</td><td>Partners/Customers to WH/Stock</td></tr><tr><td>PoS Orders</td><td>Delivery</td><td>POS</td><td>Never</td><td>WH/Stock to Partners/Customers</td></tr></tbody></table><p>The step options on the <a href="./warehouses.html">warehouse</a> create or use these types for you. Most are created by the three-step setup.</p><h2 id="create-an-operation-type" tabindex="-1">Create an operation type <a class="header-anchor" href="#create-an-operation-type" aria-label="Permalink to &quot;Create an operation type&quot;">​</a></h2><ol><li>Click <strong>New Operation Type</strong>.</li><li>Type the name in <strong>Operation Type</strong>, for example <strong>Returns to vendor</strong>.</li><li>Fill the <strong>General</strong> tab. The form has a top card for the name, then the <strong>General</strong> tab.</li><li>Click <strong>Create</strong>.</li></ol>',6)),r(o,{src:"/images1/inventory/optype_create.png",alt:"Create Operation Type form with name, type Delivery, prefix RTV and locations fieldset"}),t[2]||(t[2]=e('<h3 id="general-tab" tabindex="-1">General tab <a class="header-anchor" href="#general-tab" aria-label="Permalink to &quot;General tab&quot;">​</a></h3><ul><li><strong><em>Operation Type:</em></strong> Required. Choose <strong>Receipt</strong>, <strong>Delivery</strong>, <strong>Internal</strong>, <strong>Dropship</strong> or <strong>Manufacture</strong>. The default is <strong>Receipt</strong>. The choice sets default locations. For example, choosing <strong>Delivery</strong> fills <strong>WH/Stock</strong> to <strong>Partners/Customers</strong>.</li><li><strong><em>Sequence Prefix:</em></strong> Required. The letters in the document number, such as <strong>IN</strong> in <strong>WH/IN/11</strong>.</li><li><strong><em>Warehouse:</em></strong> The site that owns the type.</li><li><strong>Reservation Method:</strong> Radio buttons. <strong>At Confirm</strong> reserves stock when the document is confirmed. <strong>Manual</strong> waits until you click <strong>Check Availability</strong>.</li><li><strong><em>Company:</em></strong> Your current company.</li><li><strong>Return Type:</strong> The type used when you click <strong>Return</strong>. Receipts return through Delivery Orders and the reverse.</li><li><strong><em>Create Backorder:</em></strong> <strong>Ask</strong>, <strong>Always</strong> or <strong>Never</strong>. See <a href="./../operations/backorders-and-returns.html">Backorders and returns</a>.</li><li><strong>Move Type:</strong> For internal types. <strong>As soon as possible</strong> or <strong>When all products are ready</strong>.</li></ul><h3 id="lots-serial-fieldset" tabindex="-1">Lots/Serial fieldset <a class="header-anchor" href="#lots-serial-fieldset" aria-label="Permalink to &quot;Lots/Serial fieldset&quot;">​</a></h3><p>Shows with the traceability setting on.</p><ul><li><strong>Create New:</strong> A toggle. Lets users type new lot or serial numbers on this operation.</li><li><strong>Use Existing:</strong> A toggle. Lets users pick numbers that already exist, or leave the field empty.</li></ul><h3 id="locations-fieldset" tabindex="-1">Locations fieldset <a class="header-anchor" href="#locations-fieldset" aria-label="Permalink to &quot;Locations fieldset&quot;">​</a></h3><ul><li><strong><em>Source Location:</em></strong> The default &quot;from&quot; place for new documents. Required.</li><li><strong><em>Destination Location:</em></strong> The default &quot;to&quot; place. Required.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>These defaults are only a start. Routes and rules can choose other locations on a real document. See <a href="./../routes/routes-and-rules.html">Routes and rules</a>.</p></div><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Edit</strong> and <strong>View</strong> open a record.</li><li><strong>Delete</strong> archives a type. One that documents still use cannot be deleted.</li><li>Restore archived types from the <strong>Archived</strong> tab.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./warehouses.html">Warehouses</a></li><li><a href="./locations.html">Locations</a></li><li><a href="./../operations/">Transfers overview</a></li></ul>',12))])}const f=s(d,[["render",l]]);export{y as __pageData,f as default};
